import test from'node:test';import assert from'node:assert/strict';import{assessTypeRepairAcceptance}from'./type-repair-acceptance.mjs';import{installHash,installJson}from'./ci-install-grant.mjs';import{FIXTURE_PATH}from'./type-only-repair.mjs';
function fixture(){const body={format:1,kind:'ERASED_FIXTURE_CAST_SOURCE_COMPATIBILITY_NOT_RELEASE',original:'a'.repeat(40),candidate:'b'.repeat(40),compilerCandidate:'b'.repeat(40),releaseAuthorized:false,otherTrackedInputsByteIdentical:true,originalFailedCompilerPreserved:true,fixture:{path:FIXTURE_PATH}};return{sourceProof:{...body,proofSha256:installHash(installJson(body))},original:{kind:'AUTHENTICATED_ORIGINAL_UNIT_EVIDENCE_NOT_COMBINED_RELEASE',releaseAuthorized:false,expected:{candidate:body.original,controller:'c'.repeat(40),baseline:'d'.repeat(40),runId:1},fingerprint:'e'.repeat(64),reusable:[{id:'unit1',origin:{}}],rerun:[],completeRequiredUnits:['unit1']},originalSnapshot:{run:{id:1,conclusion:'failure',status:'completed',run_attempt:1},jobs:[...['controller-tests','migrations','build'].map(name=>({name,conclusion:'success'})),...['typecheck','verify'].map(name=>({name,conclusion:'failure'}))]},focused:{kind:'AUTHENTICATED_FOCUSED_FILE_OUTCOMES_NOT_COMBINED_RELEASE',origin:{candidate:body.candidate,controller:'c'.repeat(40),baseline:'d'.repeat(40),runId:2},failedFiles:0,originalFocusedExitCode:0,files:[{path:FIXTURE_PATH,state:'PASSED'}]},focusedSnapshot:{run:{id:2,status:'completed',conclusion:'success',run_attempt:1},jobs:[{name:'typecheck',id:3,status:'completed',conclusion:'success',steps:[{name:'Run bash ../automation/.github/ci/typecheck.sh',conclusion:'success'}]}]}};}
test('retains failed origin and explicit combined identity without creating full gate PASS',()=>{const p=assessTypeRepairAcceptance(fixture());assert.equal(p.originalRunConclusion,'failure');assert.equal(p.fullGatePassCreated,false);assert.equal(p.releaseAuthorized,false);assert(p.requiresNewExactCandidateSystemTestingBuild);});
for(const[name,change]of[['missing runtime unit',f=>f.original.reusable=[]],['failed runtime unit',f=>f.original.rerun=[{id:'unit1'}]],['new original failure',f=>f.originalSnapshot.jobs.push({name:'test (unit1)',conclusion:'failure'})],['skipped prerequisite',f=>f.originalSnapshot.jobs[0].conclusion='skipped'],['missing whole compiler',f=>f.focusedSnapshot.jobs=[]],['compiler command skipped',f=>f.focusedSnapshot.jobs[0].steps[0].conclusion='skipped'],['focused process failure',f=>f.focused.originalFocusedExitCode=1],['different tested fixture',f=>f.focused.files[0].path='test/other.test.ts'],['tampered source proof',f=>f.sourceProof.candidate='f'.repeat(40)]])test('refuses '+name,()=>{const f=fixture();change(f);assert.throws(()=>assessTypeRepairAcceptance(f));});
